/**
 * The seam between checkout and the payment provider (DEMO_MODE.md §5). Field
 * names that go straight onto the wire keep ZaloPay's snake_case: renaming
 * them would only add a mapping layer to get wrong.
 */
export const ZALOPAY_CLIENT = Symbol('ZALOPAY_CLIENT');

export type CreateOrderInput = {
  /** Generated by `CheckoutService` and stored before this call; never by the client. */
  appTransId: string;
  /** `app_user`: who is paying (the learner's id); the provider rejects a blank one. */
  appUser: string;
  amountVnd: number;
  /** Shown in the ZaloPay app. */
  description: string;
  embedData: { courseId: string; purchaseId: string };
  expiresAt: Date;
};

export type CreateOrderResult = {
  qrCode: string;
  orderUrl: string;
  /** For the log only; no column keeps it. */
  zpTransToken: string;
};

export type QueryOrderResult = {
  /** 1 paid, 2 failed, 3 still processing. */
  returnCode: 1 | 2 | 3;
  returnMessage: string;
  /** Present when `returnCode` is 1: becomes `PaymentAttempt.providerTransId`. */
  zpTransId?: string;
  /** Present when `returnCode` is 1: must equal the amount snapshotted on the attempt. */
  amountVnd?: number;
};

/** The parsed `data` of a callback whose MAC has already been verified. */
export type ZaloPayCallbackData = {
  app_id: number;
  app_trans_id: string;
  /** Epoch milliseconds. */
  app_time: number;
  /** VND. */
  amount: number;
  zp_trans_id: string;
  /** JSON string. */
  embed_data: string;
  item: string;
};

export interface ZaloPayClient {
  createOrder(input: CreateOrderInput): Promise<CreateOrderResult>;
  queryOrder(appTransId: string): Promise<QueryOrderResult>;
  /** Throws when the MAC is wrong; never returns for an invalid signature. */
  verifyCallback(body: { data: string; mac: string }): ZaloPayCallbackData;
}
